package com.vitalminds.service;
import com.vitalminds.model.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class HealthInsightsService {
 public int score(User u, HealthRecord r, List<ActivityLog> a, List<SleepLog> s){int x=65; if(u.getHeightCm()!=null&&u.getWeightKg()!=null&&u.getHeightCm()>0){double bmi=u.getWeightKg()/Math.pow(u.getHeightCm()/100,2); if(bmi>=18.5&&bmi<25)x+=10; else if(bmi>=25&&bmi<30)x+=5;} if(r!=null){if(r.getGlucose()!=null&&r.getGlucose()>=70&&r.getGlucose()<=99)x+=6;if(r.getSystolic()!=null&&r.getDiastolic()!=null&&r.getSystolic()<120&&r.getDiastolic()<80)x+=7;if(r.getCholesterol()!=null&&r.getCholesterol()<200)x+=5;if(r.getHemoglobin()!=null&&r.getHemoglobin()>=12&&r.getHemoglobin()<=17)x+=3;} if(!a.isEmpty()&&a.get(0).getSteps()!=null&&a.get(0).getSteps()>=7000)x+=2;if(!s.isEmpty()&&s.get(0).getHours()!=null&&s.get(0).getHours()>=7&&s.get(0).getHours()<=9)x+=2;return Math.min(99,x);}
 public List<String> recommendations(User u,HealthRecord r,List<ActivityLog>a,List<SleepLog>s){List<String> out=new ArrayList<>();if(r==null)out.add("Upload a recent health report to unlock report-based insights.");else{if(r.getGlucose()!=null&&r.getGlucose()>99)out.add("Track repeated glucose readings and review persistent changes with a clinician.");if(r.getSystolic()!=null&&r.getSystolic()>=130)out.add("Repeat blood-pressure measurements correctly and discuss repeated elevated readings with a clinician.");if(r.getCholesterol()!=null&&r.getCholesterol()>=200)out.add("Consider discussing your full lipid profile and lifestyle factors with a qualified clinician.");}if(a.isEmpty()||a.get(0).getSteps()==null||a.get(0).getSteps()<7000)out.add("Build toward regular daily movement that fits your ability and routine.");if(s.isEmpty()||s.get(0).getHours()==null||s.get(0).getHours()<7)out.add("Aim for a consistent sleep routine and adequate sleep opportunity.");if(out.isEmpty())out.add("Your current dashboard has a useful baseline. Keep logging consistently and review trends rather than single readings.");return out;}
 public List<HealthAlert> buildAlerts(User u,HealthRecord r){List<HealthAlert> out=new ArrayList<>(); if(r==null)return out; if(r.getSystolic()!=null&&r.getSystolic()>=140){out.add(make(u,"ATTENTION","Blood pressure reading","Your latest systolic reading is elevated. Repeat measurements and seek professional advice for persistent elevation."));} if(r.getGlucose()!=null&&r.getGlucose()>=126){out.add(make(u,"ATTENTION","Glucose reading","Your latest glucose value is in a range that deserves professional interpretation, including whether the test was fasting."));} if(r.getCholesterol()!=null&&r.getCholesterol()>=240){out.add(make(u,"ATTENTION","Cholesterol reading","Your latest total cholesterol value is high enough to discuss with a qualified clinician and the rest of the lipid profile."));} return out;}
 private HealthAlert make(User u,String sev,String title,String msg){HealthAlert a=new HealthAlert();a.setUser(u);a.setCreatedAt(java.time.LocalDateTime.now());a.setSeverity(sev);a.setTitle(title);a.setMessage(msg);a.setReadFlag(false);return a;}
}
